// Alpha kill loop: kill distinct enemies, eat when hurt
async function eatTo(minRatio = 0.5) {
  const s = sdk.getState();
  const hp = s.player.hp, max = s.player.maxHp;
  while (hp && hp < max * minRatio) {
    const food = sdk.findInventoryItem(/shrimps|bread|cooked meat|meat|bread/i);
    if (!food) return false;
    await bot.eatFood(food);
    const s2 = sdk.getState();
    if (s2.player.hp === hp) return false; // didn't help
    hp = s2.player.hp;
  }
  return true;
}

async function killOne(pattern) {
  await bot.dismissBlockingUI();
  const npc = sdk.findNearbyNpc(pattern, { reachable: true });
  if (!npc) return 'notfound';
  const name = npc.name;
  const r = await bot.attack(npc);
  if (!r.success) return 'attack-failed:' + (r.message || '');
  await sdk.waitForCondition(() => {
    const s = sdk.getState();
    if (s.player.hp <= Math.ceil(s.player.maxHp * 0.4)) { eatTo(0.8); }
    return !s.player.inCombat;
  }, 60000);
  return 'killed ' + name;
}

globalThis.killOne = killOne;
globalThis.eatTo = eatTo;

