if (spider) {
  const r = await bot.attack(spider);
  out.push('spider attack ' + r.success);
  await sdk.waitForCondition(() => !sdk.getState().player.inCombat, 25000).catch(() => out.push('spider timeout'));
}
await bot.dismissBlockingUI();
const s = sdk.getState();
out.push('npcs: ' + (s.nearbyNpcs || []).map(n => n.name + ' L' + n.combatLevel).join(', '));
return out;

await sdk.waitForCondition(() => !sdk.getState().player.inCombat, 20000).catch(()=>{});
await bot.dismissBlockingUI();
